@startuml

class Building {
  + m : int
}

class Floor {
  + floorNumber : int
}

class Elevator {
  + elevatorId : int
}

class Button {
  + isLit : boolean
  + press()
  + lightUp()
  + turnOff()
}

enum Direction {
  Up
  Down
}

class FloorButton {
  + direction : Direction
}

class ElevatorButton {
  + floorNumber : int
}

Building "1" *-- "1..*" Floor
Building "1" *-- "*" Elevator
Floor "1" *-- "0..2" FloorButton
Elevator "1" *-- "*" ElevatorButton
ElevatorButton "*" -- "1" Floor : at
FloorButton "*" -- "1" Floor : at

@enduml

